            0x03: 0x0000,  # SHUNT2
            0x04: 0x0000,  # VBUS2
            0x05: 0x0000,  # SHUNT3
            0x06: 0x0000,  # VBUS3
            0x07: 0x7FF8,  # CRIT1
            0x08: 0x7FF8,  # WARN1
            0x09: 0x7FF8,  # CRIT2
            0x0A: 0x7FF8,  # WARN2
            0x0B: 0x7FF8,  # CRIT3
            0x0C: 0x7FF8,  # WARN3
            0x0D: 0x0000,  # SHUNT_SUM
            0x0E: 0x7FFE,  # SHUNT_SUM_LIMIT
            0x0F: 0x0002,  # MASK_ENABLE
            0x10: 0x2710,  # PV_UPPER
            0x11: 0x2328,  # PV_LOWER
            0xFE: 0x5449,  # MANUF_ID
            0xFF: 0x3220   # DIE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address {addr}")

        value = self.regs[addr]

        if nbytes == 1:
            # For single byte access, return only the relevant bits
            if addr in [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06]:
                # SHUNTx and VBUSx registers have 12-bit fields
                value = value & 0xFFF
            elif addr in [0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C]:
                # CRITx and WARNx registers have 13-bit fields
                value = value & 0x1FFF
            else:
                raise ValueError(f"Single byte access not supported for register {addr}")

        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address {addr}")

        if addr == 0x00:
            # CONFIG register has special behavior
            if data & 0x8000:  # RST bit
                self.regs[addr] = 0x7127  # Reset all registers to default
            else:
                self.regs[addr] = data
        else:
            if nbytes == 1:
                # For single byte access, update only the relevant bits
                if addr in [0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06]:
                    # SHUNTx and VBUSx registers have 12-bit fields
                    self.regs[addr] = (self.regs[addr] & ~0xFFF) | (data & 0xFFF)
                elif addr in [0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C]:
                    # CRITx and WARNx registers have 13-bit fields
                    self.regs[addr] = (self.regs[addr] & ~0x1FFF) | (data & 0x1FFF)
                else:
                    raise ValueError(f"Single byte write not supported for register {addr}")
            else:
                self.regs[addr] = data

