class INA3221_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()
        # Initialize registers to their reset values
        for reg_addr in range(0x00, 0x11):  # Exclude MANUF_ID and DIE_ID
            self.regs[reg_addr] = self.get_reset_value(reg_addr)

    def get_reset_value(self, reg_addr):
        if reg_addr == 0xFE:
            return 0x5449  # Manufacturer ID
        elif reg_addr == 0xFF:
            return 0x3220  # Die ID
        else:
            return self.get_register_reset_value(reg_addr)

    def get_register_reset_value(self, reg_addr):
        ir = self.device_info['registers']
        for reg in ir:
            if reg['addr'] == hex(reg_addr)[2:].upper():
                return reg['reset']
        raise ValueError(f"Register {reg_addr} not found in device IR")

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr in self.regs:
            value = self.regs[addr]
            if nbytes == 1:
                return value >> 8  # Extract bits 15:8 for single-byte reads
            return value
        raise KeyError(f"Register {addr} not found in simulator")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr in self.regs:
            if nbytes == 1:
                value = self.regs[addr] & 0xFF00 | (data & 0xFF)  # Update bits 15:8
            else:
                value = data
            self.regs[addr] = value
        else:
            raise KeyError(f"Register {addr} not found in simulator")

